    components = []
    unseen = set(active)
    while unseen:
        start = unseen.pop()
        comp = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            for p in ((r-1,c), (r+1,c), (r,c-1), (r,c+1)):
                if p in unseen:
                    unseen.remove(p)
                    comp.add(p)
                    q.append(p)
        components.append(comp)
